define(['jquery', 'mage/url', 'Magento_Ui/js/modal/modal', 'Magento_Customer/js/customer-data', 'mage/url', 'mage/storage', 'mage/translate', 'mage/mage', 'jquery/validate', 'Eighteentech_MobileLogin/js/jquery.fancybox.min', 'mage/cookies'], function($, url, modal, customerData, urlBuilder, storage, $t) {
    'use strict';
    $.widget('eighteentech.mobileLogin', {
        options: {
            login: '#eighteentech-login-popup',
            nextRegister: '#customer-popup-registration',
            register: '#customer-popup-register',
            prevLogin: '#customer-popup-sign-in',
            class_login: [],
            class_register: [],
            isPopup: '',
            formLoginUrl: '',
            forgotFormUrl: '',
            createFormUrl: '',
            recaptchaLogin: '',
            recaptchaForgot: '',
            recaptchaCreate: '',
            recaptchaSitekey: '',
            recaptchaTheme: '',
            recaptchaType: '',
            recaptchaSize: '',
            popuphtml: ''
        },
        _create: function() {
            this._EventListener();
        },
        _init: function() {
            this.options.popuphtml = $("#login_overlay").html();
        },
        _EventListener: function() {
            var $widget = this;
            var options = {
                type: 'popup',
                responsive: true,
                innerScroll: true,
                modalClass: "login_popup_form",
                buttons: [{
                    text: $.mage.__('OK'),
                    class: '',
                    click: function() {
                        this.closeModal();
                    }
                }]
            };
            setTimeout(() => {
                $(document).ready(function() {
                    var previousPage = localStorage.getItem('previous_page_url');
                    if (previousPage === 'mobilelogin') {
                        $("#customer-popup-registration").hide();
                        if ($("#login_overlay").length) {
                            $widget._OnClick($(this));
                            modal(options, $('#login_overlay'));
                            $('#login_overlay').modal('openModal');
                        } else {
                            console.warn("#login_overlay not found in DOM");
                        }
                        localStorage.removeItem('previous_page_url');
                    }
                });
            }, 500);
            $(document).on('click', '#customer-account-link-id', function(e) {
                e.preventDefault();
                $("#customer-popup-registration").hide();
                if ($("#login_overlay").length) {
                    $widget._OnClick($(this));
                    modal(options, $('#login_overlay'));
                    $('#login_overlay').modal('openModal');
                    $('#double_send_otp_login').prop('disabled', true);
                } else {
                    console.warn("#login_overlay not found in DOM");
                }
            });
            $(document).on('click', '#double_send_otp_login', function(e) {
                e.preventDefault();
                var $form = $("#customer-popup-login-form11");
                var mobile = $form.find("#mobile_login").val().trim();
                var mob_regex = /^[6-9]\d{9}$/;
                $('.smserror, .success_msg_mobile, .captcha_err').html("");
                if (!mob_regex.test(mobile)) {
                    $(".success_msg_mobile").html('<div class="smserror"><p style="color:red;">Please enter a valid 10-digit mobile number.</p></div>');
                    return false;
                }
                var sendotpurllogin = url.build('smsprofile/otp/check');
                $.ajax({
                    url: sendotpurllogin,
                    method: "POST",
                    data: {
                        mobile: mobile,
                        eventType: 'customer_login_otp',
                        resend: 0,
                        isResend: 0
                    },
                    dataType: "json",
                    showLoader: true
                }).done(function(response) {
                    var finalValue = false;
                    if (response.isExist) {
                        const existDecoded = atob(response.isExist);
                        const reversed = existDecoded.split('').reverse().join('');
                        finalValue = atob(reversed);
                    }
                    const decoded = atob(atob(response.Success));
                    const parts = decoded.split(".");
                    const decoded1 = atob(parts[1]).split("").reverse().join("");
                    const finalMsg = atob(decoded1);
                    if (finalMsg != 'success-' + mobile && !finalValue) {
                        $("#popup-title").html("Register with us <div class='number_seprate'>+91" + mobile + "<span id='change-number'> Change</span></div>");
                        $(".success_msg_mobile").html('<div class="smserror"><p >This number is not registered with us. Please register to continue shopping.</p></div>').show();
                        $("#customer-popup-registration").show();
                        $form.find("#double_send_otp_login").hide();
                        $(".tab-recaptcha").hide();
                        $form.find(".mobile-section").hide();
                    } else if (finalMsg == 'success-' + mobile && finalValue) {
                        $(".success_msg_mobile").html("");
                        $widget._AjaxSendOtp();
                    } else if (finalValue && finalMsg != 'success-' + mobile) {
                        $(".success_msg_mobile").html('<div class="smserror"><p style="color:red !important;">Something want wrong, please refersh the page.</p></div>');
                    }
                });
            });
            $(document).on('click', '#double_send_otp_login-resend', function(e) {
                e.preventDefault();
                var $form = $("#customer-popup-login-form11");
                var mobile = $form.find("#mobile_login").val().trim();
                var mob_regex = /^[6-9]\d{9}$/;
                $('.smserror, .success_msg_mobile, .captcha_err').html("");
                if (!mob_regex.test(mobile)) {
                    $(".success_msg_mobile").html('<div class="smserror"><p style="color:red;">Please enter a valid 10-digit mobile number.</p></div>');
                    return false;
                }
                var sendotpurllogin = url.build('smsprofile/otp/check');
                $.ajax({
                    url: sendotpurllogin,
                    method: "POST",
                    data: {
                        mobile: mobile,
                        eventType: 'customer_login_otp',
                        resend: 0,
                        isResend: 0
                    },
                    dataType: "json",
                    showLoader: true
                }).done(function(response) {
                    var finalValue = false;
                    if (response.isExist) {
                        const existDecoded = atob(response.isExist);
                        const reversed = existDecoded.split('').reverse().join('');
                        finalValue = atob(reversed);
                    }
                    const decoded = atob(atob(response.Success));
                    const parts = decoded.split(".");
                    const decoded1 = atob(parts[1]).split("").reverse().join("");
                    const finalMsg = atob(decoded1);
                    if (finalMsg != 'success-' + mobile && !finalValue) {
                        $("#popup-title").html("Register with us <div class='number_seprate'>+91" + mobile + "<span id='change-number'> Change</span></div>");
                        $(".success_msg_mobile").html('<div class="smserror"><p>This number is not registered with us. Please register to continue shopping.</p></div>');
                        $("#customer-popup-registration").show();
                        $form.find("#double_send_otp_login").hide();
                        $(".tab-recaptcha").hide();
                        $form.find(".mobile-section").hide();
                    } else if (finalMsg == 'success-' + mobile && finalValue) {
                        $(".success_msg_mobile").html("");
                        $(".tab-recaptcha").hide();
                        $widget._AjaxSendOtp();
                    } else if (finalValue && finalMsg != 'success-' + mobile) {
                        $(".success_msg_mobile").html('<div class="smserror"><p style="color:red !important;">Something want wrong, please refersh the page.</p></div>');
                    }
                });
            });
            $(document).on('click', '#verif_otp_login', function() {
                return $widget._AjaxOtpVerify();
            });
            $(document).on('click', '.action-close', function(e) {
                location.reload();
            });
            $(document).on('click', '#change-number-id, #change-number', function() {
                var $form = $("#customer-popup-login-form11");
                var mobile = $form.find("#mobile_login").val().trim();
                $("#double_send_otp_login").addClass('dsabled-active');
                $("#customer-popup-registration").hide();
                $form.find("#mobile_login").val(mobile).show().focus();
                $form.find("#double_send_otp_login").show().attr("disabled", false);
                $("#popup-title").html("Enter mobile number");
                $(".captcha_err, .smserror, .success_msg_mobile").html("");
                $form.find("#verif_otp_login").hide();
                $form.find(".mobile-section").show();
                $("#resend-otp-timer").hide();
                $("#mb-6-text-center").hide();
                $(".tab-recaptcha").show();
                $(".tab-recaptcha").removeClass('d-none');
                grecaptcha.reset();
            });
            $(document).ready(function() {
                $('.otp-field').on('input', function() {
                    if ($(this).val().length === 1) {
                        $(this).next('.otp-field').focus();
                    }
                });
                $('.otp-field').on('keydown', function(e) {
                    if (e.key === "Backspace" && $(this).val() === "") {
                        $(this).prev('.otp-field').focus();
                    }
                });
            });
            $(document).keypress(function(event) {
                if (event.which == '13') {
                    if ($("#digit-1").val() != "" && $("#digit-2").val() != "" && $("#digit-3").val() != "" && $("#digit-4").val() != "") {
                        $("#verif_otp_login").trigger("click");
                    }
                    event.preventDefault();
                }
            });
        },
        _OnClick: function($this) {
            $.fancybox({
                openEffect: 'none',
                closeEffect: 'none',
                width: "auto",
                height: 'auto',
                fitToView: false,
                autoSize: false,
                maxWidth: '98%',
                content: "",
            });
            $('#login-recaptcha,#fogot-recaptcha,#create-recaptcha').val('');
            var element_render = 'tab-login-recaptcha';
            var validate = 'login-recaptcha';
            if ($('#' + element_render).children().length === 0 && this.options.recaptchaSitekey !== "") {
                grecaptcha.render(element_render, {
                    'sitekey': this.options.recaptchaSitekey,
                    'theme': "light",
                    'type': "image",
                    'size': "normal",
                    'callback': function(response) {
                        if (response.length > 0) {
                            $('#' + validate).val('success');
                            $('#double_send_otp_login').prop('disabled', false);
                            $('#double_send_otp_login').removeClass('disabled-active');
                        }
                    }
                });
            }
        },
        _AjaxSendOtp: function() {
            var self = this;
            var $form = $("#customer-popup-login-form11");
            $('.smserror, .success_msg_mobile, .captcha_err').hide();
            var sendotpurl = url.build('smsprofile/otp/send');
            var mobile = $form.find("#mobile_login").val();
            var captchaResponse = $form.find("#g-recaptcha-response").val();
            $.ajax({
                showLoader: true,
                url: sendotpurl,
                method: "POST",
                data: {
                    mobile: mobile,
                    eventType: 'cod_otp',
                    resend: 0,
                    isResend: 1,
                    captcha: captchaResponse
                },
                dataType: "json"
            }).done(function(response) {
                var decodedData = atob(response.Success);
                decodedData = decodedData.split("").reverse().join("");
                decodedData = atob(decodedData);
                if (decodedData === 'success-' + mobile) {
                    $("#digit-1").val('');
                    $("#digit-2").val('');
                    $("#digit-3").val('');
                    $("#digit-4").val('');
                    $form.find('.mobile-section').attr('readonly', 'true').hide();
                    $form.find("#double_send_otp_login").hide();
                    $form.find("#verif_otp_login").show();
                    $form.find(".success_msg_mobile").html("<p class='success' style='color:green;'>If this account exists, an OTP has been sent.</p>");
                    $("#popup-title").html("Verify with OTP sent to +91" + mobile + " <span id='change-number-id'>Change</span>");
                    $("#mb-6-text-center, #otp-verifaction").show();
                    $("#resend-otp-timer").show();
                    $(".tab-recaptcha").hide();
                    $(".tab-recaptcha").addClass('d-none');
                    clearInterval(self.timer);
                    self._loadTimer(120);
                    $(document).find(".captcha_err").remove();
                } else {
                    $(".tab-recaptcha").show();
                    $form.find(".captcha_err").remove();
                    $('.smserror, .success_msg_mobile, .captcha_err').show();
                    $(".success_msg_mobile").html('<div class="smserror"><p class="captcha_err" style="color:red;">' + decodedData + '</p></div>');
                }
            }).fail(function(xhr, status, error) {
                if (xhr.status == 429) {
                    $form.find(".captcha_err").remove();
                    $(".success_msg_mobile").show();
                    $(".success_msg_mobile").html('<div class="smserror"><p class="captcha_err" style="color:red;">Too many OTP requests. Please wait a few minutes before trying again.</p></div>');
                } else {
                    console.error("OTP API error:", xhr.status, error);
                    $(".success_msg_mobile").show();
                    $form.find(".captcha_err").remove();
                    $(".success_msg_mobile").html('<div class="smserror"><p class="captcha_err" style="color:red;">Something went wrong. Please try again later.</p></div>');
                };
            });
            return false;
        },
        _AjaxOtpVerify: function() {
            var $form = $("#customer-popup-login-form11");
            var otp = $("#digit-1").val() + $("#digit-2").val() + $("#digit-3").val() + $("#digit-4").val();
            if (otp === '') {
                alert('Please enter OTP');
                return false;
            }
            var mobile = $form.find("#mobile_login").val();
            var captcha_res = $(".login_popup_form #g-recaptcha-response").val();
            var isCheckout = 0;
            var isMinicart = 0;
            if ($('#login_overlay').hasClass('cart-icon-div')) {
                isCheckout = 1;
                $('#login_overlay').removeClass('cart-icon-div');
            }
            if ($('#footer-cart-btn').hasClass('cart-icon-div')) {
                isCheckout = 1;
                $('#footer-cart-btn').removeClass('cart-icon-div');
            }
            if ($('#top-cart-btn-checkout').hasClass('prodceed-btn')) {
                isCheckout = 1;
                $('#top-cart-btn-checkout').removeClass('prodceed-btn');
            }
            if ($('#minicart-wrapper-id').hasClass('clicked')) {
                isMinicart = 1;
            }
            $.ajax({
                showLoader: true,
                url: location.origin + '/smsprofile/otp/verify',
                method: "POST",
                data: {
                    otp: otp,
                    mobile: mobile,
                    captcha_res: captcha_res,
                    isCheckout: isCheckout
                },
                dataType: "json"
            }).done(function(response) {
                const jsonData = JSON.parse(atob(atob(response.message)));
                const finalMsg = atob(atob(jsonData.status).split("").reverse().join(""));
                if (finalMsg === 'Verified-' + otp) {
                    $.ajax({
                        showLoader: true,
                        url: location.origin + "/smsprofile/account/loginpost",
                        method: "POST",
                        data: {
                            "login": {
                                "username": mobile,
                                "otp": otp,
                                "ischeckout": isCheckout
                            }
                        },
                        dataType: "json",
                        success: function(result) {
                            var sections = ['cart', 'customer', 'emailPopup'];
                            customerData.invalidate(sections);
                            customerData.reload(sections, true);
                            var cartData = customerData.get('cart');
                            var count = cartData().summary_count || 0;
                            var now = new Date();
                            now.setTime(now.getTime() + (10 * 1000));
                            $form.find(".success_msg_mobile").html("<p class='success' style='color:green;'>OTP Verified Successfully!</p>");
                            if (count > 0 && response.addresses && isMinicart == 0 && isCheckout == 0) {
                                $.cookie('cartOpen', '0', {
                                    path: '/',
                                    expires: now
                                });
                                $.cookie('isLoginGT', '1', {
                                    path: '/',
                                    expires: now
                                });
                                location.href = window.checkout.checkoutUrl + "#payment";
                            } else if (count > 0 && !response.addresses && isCheckout == 0 && isMinicart == 0) {
                                $.cookie('cartOpen', '0', {
                                    path: '/',
                                    expires: now
                                });
                                $.cookie('isLoginGT', '1', {
                                    path: '/',
                                    expires: now
                                });
                                location.href = window.checkout && window.checkout.shoppingCartUrl ? window.checkout.shoppingCartUrl : '/checkout/cart/';
                            } else if (count > 0 && response.addresses && isCheckout == 1 && isMinicart == 0) {
                                $.cookie('cartOpen', '0', {
                                    path: '/',
                                    expires: now
                                });
                                $.cookie('isLoginGT', '1', {
                                    path: '/',
                                    expires: now
                                });
                                location.href = window.checkout.shoppingCartUrl;
                            } else if (count > 0 && !response.addresses && isCheckout == 1 && isMinicart == 0) {
                                $.cookie('cartOpen', '0', {
                                    path: '/',
                                    expires: now
                                });
                                $.cookie('isLoginGT', '1', {
                                    path: '/',
                                    expires: now
                                });
                                location.href = window.checkout.shoppingCartUrl;
                            } else {
                                $.cookie('cartOpen', '1', {
                                    path: '/',
                                    expires: now
                                });
                                $.cookie('isLoginGT', '1', {
                                    path: '/',
                                    expires: now
                                });
                                location.reload();
                            }
                        }
                    });
                } else {
                    $('.smserror, .success_msg_mobile, .captcha_err').show();
                    $(".success_msg_mobile").html('<div class="smserror"><p class="success" style="color:red;">OTP is not Verified!</p></div>');
                }
            });
            return false;
        },
        _loadTimer: function(seconds) {
            var self = this;
            if (self.timer) {
                clearInterval(self.timer);
            }
            var remaining = seconds;
            $('.main-timer').css('display', 'inline-block');
            $('#otp-resend').prop('disabled', true);
            $("#otp-resend").text('Resend in');
            $('#otp-resend').css({
                'color': '#b9b9b9',
                'text-decoration': 'none'
            });
            self.timer = setInterval(function() {
                var m = Math.floor(remaining / 60);
                var s = remaining % 60;
                m = m < 10 ? '0' + m : m;
                s = s < 10 ? '0' + s : s;
                $('#timer').text(m + ':' + s);
                remaining--;
                if (remaining < 0) {
                    clearInterval(self.timer);
                    $('#otp-resend').prop('disabled', false);
                    $('#otp-resend').css('color', '#cb2227');
                    $('.main-timer').hide();
                    $("#otp-resend").html('<a href="#" id="double_send_otp_login-resend">Resend OTP</a>');
                }
            }, 1000);
        }
    });
    return $.eighteentech.mobileLogin;
});